/* ideal cycles computed from the lesson's numbers (v in units of v1, p in units of p1, gamma 1.4):
   Otto r = 8 with T3/T2 = 1800/689.2; Diesel r = 16, cut-off 2; dual r = 12, alpha 1.5, cut-off 1.5 (an illustration) */
function Q4_cyc(kind){const G=1.4,N=36,pts=[],heat=[];let r,v2,p2,p3,v3;
 if(kind==='otto'){r=8;v2=1/r;p2=Math.pow(r,G);p3=p2*1800/689.2;v3=v2}
 else if(kind==='diesel'){r=16;v2=1/r;p2=Math.pow(r,G);p3=p2;v3=2*v2}
 else {r=12;v2=1/r;p2=Math.pow(r,G);p3=1.5*p2;v3=1.5*v2}
 for(let i=0;i<=N;i++){const v=1-(1-v2)*i/N;pts.push([v,Math.pow(1/v,G)])}
 heat.push([v2,p2]);if(p3>p2)heat.push([v2,p3]);if(v3>v2)heat.push([v3,p3]);
 for(let i=0;i<=N;i++){const v=v3+(1-v3)*i/N;pts.push([v,p3*Math.pow(v3/v,G)])}
 return {pts,heat}}
/* a small p-v plot of one cycle in a box x,y,w,h (p up to 50 p1, v up to v1); the heat-in line in orange */
