function EXTRA(R,ICON){
 /* hook: two cylinders, the gas squeezed into 1/8 and 1/16 of the length */
 ICON.q4Pet=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${Q4_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${Q4_T(20,36,'petrol, Otto cycle',{fs:24,fw:800,fill:BLU})}${Q4_squeeze(20,62,220,8,BLU)}${Q4_T(360,108,'r = 8',{fs:26,fw:800,a:'end',fill:BLU})}</g>`;
 ICON.q4Dsl=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${Q4_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${Q4_T(20,36,'diesel',{fs:24,fw:800,fill:ORG})}${Q4_squeeze(20,62,220,16,ORG)}${Q4_T(360,108,'r = 16',{fs:26,fw:800,a:'end',fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.q4Rank=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${Q4_T(95,24,'same r = 16',{fs:22,fw:800,a:'middle',fill:BLU})}${Q4_T(320,24,'same peak',{fs:22,fw:800,a:'middle',fill:GRN})}${Q4_bars([['Otto',67.0,GRN],['Diesel',61.4,'#ADB5BD']],20,290,210,70,70,20,Q4_pc)}${Q4_bars([['Otto',56.5,'#ADB5BD'],['Diesel',61.4,GRN]],250,290,210,70,70,20,Q4_pc)}</g>`;
 ICON.q4Gas=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${Q4_bars([['constant cv',1800,'#ADB5BD'],['variable cv',1553,ORG]],60,290,250,2000,120,70,Q4_K)}${Q4_T(210,22,'247 K cooler',{fs:24,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.q4Ind=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${Q4_mini('otto',40,20,340,240,GRN)}<rect x="80" y="250" width="290" height="14" fill="${RED}" fill-opacity=".35" stroke="${RED}" stroke-width="2"/>${Q4_T(80,300,'− pumping loop',{fs:22,fw:800,fill:RED})}${Q4_T(210,332,'362 J = 380 − 18 J',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`;
}
